package main

var learnCSharp = learnTopic{
	Name:   "C#",
	Match:  []string{"c#", ".cs", ".csx"},
	Source: "Microsoft Learn: What's new in C# 12, 13 and 14 · C# version history · C# reference (patterns, ??, switch, records, init, required, using, nameof, raw strings, exceptions) · Nullable reference types · Async scenarios · .NET coding conventions · Identifier names · Comparing strings · dotnet format",
	Sections: []learnSection{
		{Title: "Variables and types", Keys: []string{"=", "bool", "double", "decimal"}, Items: []learnItem{
			{Use: "var", Why: "The compiler works out the type. Use it only when the type is clear from the right side: a new, a cast or a literal. Write the type when the value comes from a method call.",
				Like: "Like a parcel with a clear window: you may skip the label only when everyone can see what is inside.", Example: "var users = new List<User>();\nvar count = 0;"},
			{Use: "string · int", Keys: []string{"system.string", "system.int32"}, Why: "Use the language keywords, not the runtime names: string, not System.String. Prefer int to unsigned types: most libraries use int.",
				Like: "Like saying 'milk' instead of the dairy's product code.", Example: "string name = \"Ana\";\nint count = items.Count;"},
			{Use: "Person p = new(\"Ana\");", Keys: []string{"new()", "new"}, Why: "Target-typed new (C# 9+). The type is written once, on the left. It works when the variable type and the object type are the same.",
				Like: "Like writing the address once on the envelope, not again on the letter inside.", Example: "Dictionary<string, int> counts = new();\nPerson p = new(\"Ana\");"},
			{Use: "int[] a = [1, 2, 3];", Keys: []string{"collection"}, Why: "A collection expression (C# 12+). It makes arrays, lists and spans. [.. a, .. b] spreads other collections into it. The .NET conventions use it for all collection types.",
				Like: "Like packing a lunchbox in one go, and tipping a second box into it.", Example: "int[] ids = [1, 2, 3];\nList<string> names = [\"Ana\", \"Ben\"];\nint[] all = [.. ids, 4];"},
		}},
		{Title: "Null safety", Keys: []string{"null"}, Items: []learnItem{
			{Use: "<Nullable>enable</Nullable>", Keys: []string{"#nullable", "nullable"}, Why: "Turns on nullable reference types in the project file. Recent .NET templates set it already. It gives warnings at compile time only; the program runs the same.",
				Like: "Like a smoke alarm: it warns you early, but it does not put out the fire.", Example: "<PropertyGroup>\n  <Nullable>enable</Nullable>\n</PropertyGroup>"},
			{Use: "string?", Why: "The ? marks a reference that may hold null. Without it, the compiler warns when null could reach the variable.",
				Like: "Like a box marked 'may be empty': you look inside before you use it.", Example: "public string? MiddleName { get; set; }\nstring? line = Console.ReadLine();"},
			{Use: "x is null · x is not null", Keys: []string{"is"}, Why: "Null checks with patterns. is null never calls an overloaded == operator. is not null needs C# 9+.",
				Like: "Like looking inside a mailbox yourself, instead of trusting a sign someone painted on it.", Example: "if (user is null)\n  return NotFound();"},
			{Use: "?.", Keys: []string{"?["}, Why: "Reads a member only when the object is not null. Otherwise the result is null. C# 14 (.NET 10) also allows it before =: customer?.Order = x.",
				Like: "Like knocking before you go in: if nobody is home, you walk on.", Example: "int? length = customer?.Name?.Length;\nhandler?.Invoke(this, EventArgs.Empty);"},
			{Use: "??", Why: "a ?? b gives a when a is not null, otherwise b. b is only worked out when it is needed.",
				Like: "Like 'use the spare key if the main key is missing'.", Example: "string name = input ?? \"Guest\";\nint count = items?.Count ?? 0;"},
			{Use: "??=", Why: "x ??= value sets x only when x is null (C# 8+). The left side must be a variable, a property or an indexer.",
				Like: "Like filling a glass only when it is empty.", Example: "_cache ??= new Dictionary<string, User>();"},
			{Use: "ArgumentNullException.ThrowIfNull", Keys: []string{"throwifnull"}, Why: "Throws when an argument is null. The argument's name is filled in for you. .NET 6+.",
				Like: "Like a door attendant who checks each guest has a ticket before they come in.", Example: "ArgumentNullException.ThrowIfNull(user);\n_repository.Add(user);"},
		}},
		{Title: "Strings", Keys: []string{"\""}, Items: []learnItem{
			{Use: "$\"Hi {name}\"", Keys: []string{"$"}, Why: "String interpolation (C# 6+). Values go into the text inside { }. The .NET conventions use it to join short strings.",
				Like: "Like a form letter: the name is written into the blank.", Example: "string msg = $\"Hi {name}, you have {count} items\";\nConsole.WriteLine($\"Total: {total:C}\");"},
			{Use: "\"\"\" raw text \"\"\"", Keys: []string{"raw"}, Why: "A raw string literal (C# 11+). It starts and ends with at least three double quotes, and needs no escapes. Over several lines, the spaces left of the closing quotes are removed from every line.",
				Like: "Like a photocopy: what you put on the glass comes out exactly as it was.", Example: "string json = \"\"\"\n  {\"name\": \"Ana\"}\n  \"\"\";"},
			{Use: "StringBuilder", Keys: []string{"append"}, Why: "Builds a long string piece by piece. The .NET conventions use it to add strings in a loop, especially with a lot of text.",
				Like: "Like threading all the beads on one string, instead of making a new necklace for each bead.", Example: "var sb = new StringBuilder();\nforeach (string line in lines) sb.AppendLine(line);\nstring text = sb.ToString();"},
			{Use: "StringComparison.Ordinal", Keys: []string{"stringcomparison", "ordinalignorecase", "equals"}, Why: "Say how to compare: string.Equals(a, b, StringComparison.OrdinalIgnoreCase). Ordinal is the safe default for matching. Use CurrentCulture for text you show to the user.",
				Like: "Like agreeing whether 'Café' and 'cafe' count as the same before you sort the post.", Example: "bool same = string.Equals(a, b,\n  StringComparison.OrdinalIgnoreCase);"},
			{Use: "nameof(x)", Keys: []string{"nameof"}, Why: "Gives the name of a variable, type or member as a string. It is worked out at compile time (C# 6+).",
				Like: "Like a name badge printed from the staff list: if the name changes, the badge follows.", Example: "throw new ArgumentException(\"Empty\", nameof(name));\nOnPropertyChanged(nameof(Title));"},
		}},
		{Title: "Classes and records", Keys: []string{"class", "struct", "interface", "public"}, Items: []learnItem{
			{Use: "record Person(string Name);", Keys: []string{"record"}, Why: "A record (C# 9+) compares by value: two records are equal when they have the same type and the same values. Good for data. Not for Entity Framework Core entities.",
				Like: "Like two printed copies of the same receipt: different paper, same receipt.", Example: "public record Person(string Name, int Age);\nvar a = new Person(\"Ana\", 30);\nbool same = a == new Person(\"Ana\", 30);"},
			{Use: "p with { Age = 8 }", Keys: []string{"with"}, Why: "Copies a record and changes some values. The original stays as it was. The copy is shallow: objects inside it are shared.",
				Like: "Like photocopying a form and changing one answer on the copy.", Example: "var older = person with { Age = person.Age + 1 };"},
			{Use: "class Shop(ILogger log)", Keys: []string{"primary"}, Why: "A primary constructor (C# 12+). Its parameters can be used in the whole class body. In a class they are not public properties; in a record they are.",
				Like: "Like the ingredients at the top of a recipe: every step below may use them.", Example: "public class Greeter(string name) {\n  public string Hello() => $\"Hi {name}\";\n}"},
			{Use: "{ get; init; }", Keys: []string{"init", "get", "set"}, Why: "An init accessor (C# 9+). The property can be set only while the object is created, for example in an object initializer. After that it cannot change.",
				Like: "Like wet concrete: you can press a handprint in while it sets, not after.", Example: "public int Id { get; init; }\nvar order = new Order { Id = 42 };"},
			{Use: "required", Why: "The property must be set in an object initializer whenever the object is created (C# 11+). The .NET conventions use it instead of constructors to force values.",
				Like: "Like the boxes marked * on a form: it is not accepted until they are filled in.", Example: "public required string Email { get; init; }\nvar user = new User { Email = \"ana@example.com\" };"},
			{Use: "namespace App;", Keys: []string{"namespace"}, Why: "A file-scoped namespace (C# 10+). It covers the whole file, with no braces. Put using directives above it.",
				Like: "Like a street name written once at the top of a list of house numbers.", Example: "using System.Text;\n\nnamespace App.Models;"},
		}},
		{Title: "Patterns and flow", Keys: []string{"if", "case", "for"}, Items: []learnItem{
			{Use: "x switch { … }", Keys: []string{"switch"}, Why: "A switch expression (C# 8+) picks one result by patterns. The compiler warns when a value is not handled. An unhandled value throws at run time.",
				Like: "Like a sorting machine that sends each letter to one tray, and stops when a letter fits no tray.", Example: "string text = code switch\n  { 200 => \"OK\", 404 => \"Not found\", _ => \"Error\" };"},
			{Use: "_ =>", Why: "The discard pattern matches any value, null included. Put it last in a switch expression to handle every other case.",
				Like: "Like the 'everything else' tray at the end of a sorting shelf.", Example: "string size = n switch\n  { < 10 => \"small\", < 100 => \"medium\", _ => \"large\" };"},
			{Use: "is { Length: > 0 }", Why: "A property pattern with a relational pattern (C# 9+). It matches when the object is not null and the property passes the test.",
				Like: "Like checking a parcel is there, and also that it weighs more than nothing.", Example: "if (name is { Length: > 0 })\n  Console.WriteLine(name);"},
			{Use: "and · or · not", Why: "Join patterns: x is >= 1 and <= 9. not binds first, then and, then or. Use parentheses to make the order clear.",
				Like: "Like a rule on a sign: 'adults, or children with an adult'. Brackets show which words belong together.", Example: "bool isDigit = c is >= '0' and <= '9';\nif (input is not (null or \"\"))\n  Process(input);"},
			{Use: "[var first, .. var rest]", Why: "A list pattern (C# 11+) matches a list item by item. .. matches zero or more items; only one .. is allowed.",
				Like: "Like checking a queue: the first person, then anyone after.", Example: "if (args is [var first, .. var rest])\n  Run(first, rest);"},
			{Use: "using var file = …;", Keys: []string{"using", "await using"}, Why: "A using declaration (C# 8+). The object is disposed at the end of the block, even after an exception. Use await using for IAsyncDisposable.",
				Like: "Like a hotel key card that stops working when you check out, however you leave.", Example: "using var stream = File.OpenRead(path);\nusing var reader = new StreamReader(stream);\nstring text = await reader.ReadToEndAsync();"},
			{Use: "foreach (char c in text)", Keys: []string{"foreach"}, Why: "Goes through every item. The .NET conventions write the item type here, not var: the collection's name does not show it.",
				Like: "Like reading each name on a list, one after another.", Example: "foreach (string name in names)\n  Console.WriteLine(name);"},
		}},
		{Title: "Async and LINQ", Keys: []string{"task", "linq"}, Items: []learnItem{
			{Use: "async Task", Keys: []string{"async"}, Why: "A method that can use await. Return Task, or Task<T> for a value. Use it for waiting work: network, files, databases.",
				Like: "Like ordering at a counter and getting a buzzer: you sit down until it buzzes.", Example: "public async Task<User?> LoadUserAsync(int id)\n  => await _db.Users.FindAsync(id);"},
			{Use: "await", Why: "Waits for a task without blocking the thread. The method pauses, and its caller can do other work.",
				Like: "Like putting the kettle on and setting the table while it boils.", Example: "string html = await http.GetStringAsync(url);\nawait File.WriteAllTextAsync(\"page.html\", html);"},
			{Use: "await Task.WhenAll(tasks)", Keys: []string{"whenall", "whenany"}, Why: "Waits for many tasks at once without blocking. Make the tasks with ToArray() first, so they all start.",
				Like: "Like sending everyone to fetch one thing each, then waiting until all are back.", Example: "var tasks = urls.Select(u => http.GetStringAsync(u))\n  .ToArray();\nstring[] pages = await Task.WhenAll(tasks);"},
			{Use: "await foreach", Why: "Reads an async stream (IAsyncEnumerable<T>) one item at a time, as each one arrives (C# 8+).",
				Like: "Like a conveyor belt in a sushi bar: you take each plate as it comes.", Example: "await foreach (string line in File.ReadLinesAsync(path))\n  Console.WriteLine(line);"},
			{Use: ".Where(…).Select(…)", Keys: []string{"where", "select", "orderby"}, Why: "LINQ filters and shapes collections. The .NET conventions use it for collection work. Put Where first, so later steps work on fewer items.",
				Like: "Like sifting flour before you weigh it: less to carry at each step.", Example: "var names = users\n  .Where(u => u.IsActive)\n  .Select(u => u.Name);"},
			{Use: "ToList() · ToArray()", Keys: []string{"tolist", "toarray"}, Why: "A LINQ query runs only when you go through it. ToList() or ToArray() runs it now and keeps the results.",
				Like: "Like a shopping list: nothing is bought until you go to the shop.", Example: "var adults = users.Where(u => u.Age >= 18).ToList();"},
		}},
		{Title: "Naming and tools", Keys: []string{"private", "internal", "//"}, Items: []learnItem{
			{Use: "PascalCase", Why: "Types, namespaces, methods, properties and all public members. Constants too, even private ones. Record parameters too: they become public properties.",
				Like: "Like capital letters on the names of streets and towns.", Example: "public const int MaxRetries = 3;\npublic decimal TotalPrice { get; set; }\npublic void SendEmail() { }"},
			{Use: "camelCase", Why: "Local variables and method parameters. Also primary constructor parameters of classes and structs.",
				Like: "Like pencil notes inside a notebook: for use inside, not on the cover.", Example: "int retryCount = 0;\nstring userName = GetUserName(userId);"},
			{Use: "_camelCase · s_name", Why: "Private and internal fields start with _. Private and internal static fields start with s_ (the .NET runtime style; set it in .editorconfig).",
				Like: "Like a 'staff only' sign on a door: the mark says it is for inside use.", Example: "private readonly ILogger _logger;\nprivate static int s_instanceCount;"},
			{Use: "IShape · TItem", Why: "Interface names start with I. Type parameters start with T, or are just T.",
				Like: "Like 'Dr.' before a name: it shows the role at a glance.", Example: "public interface IShape { double Area(); }\npublic class Box<TItem> { }"},
			{Use: "LoadUserAsync", Why: "Add Async to the names of async methods, so callers know to await them. Event handlers do not need it.",
				Like: "Like a 'hot' label on a cup: it tells you to handle it differently.", Example: "User user = await LoadUserAsync(id);\nawait SaveChangesAsync();"},
			{Use: "/// <summary>", Keys: []string{"///", "<summary>"}, Why: "XML comments describe classes, methods and all public members. Use // for short notes, on their own line.",
				Like: "Like the label on a jar: it says what is inside without opening it.", Example: "/// <summary>Gets the user by id.</summary>\n/// <param name=\"id\">The user id.</param>\npublic User Get(int id) => _users[id];"},
			{Use: "dotnet format", Keys: []string{".editorconfig", "editorconfig"}, Why: "Formats the code to match the rules in .editorconfig: whitespace, code style and analyzers.",
				Like: "Like a tailor who makes every suit follow the same pattern.", Example: "dotnet format\ndotnet format --verify-no-changes"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "async void", Why: "Only for event handlers. Its exceptions cannot be caught outside the method, and it is hard to test. Return Task instead.",
				Like: "Like posting a letter with no return address: if it fails, nobody hears back.", Example: "// instead:\npublic async Task SaveAsync()\n  => await _db.SaveChangesAsync();"},
			{Use: ".Result · .Wait()", Keys: []string{"result", "wait", "waitall", "thread.sleep"}, Why: "They block the thread and can deadlock. Errors come wrapped in AggregateException. Use await. Use await Task.Delay, not Thread.Sleep.",
				Like: "Like standing at the oven door instead of setting a timer: nobody else can use the kitchen.", Example: "// instead:\nstring text = await http.GetStringAsync(url);\nawait Task.Delay(500);"},
			{Use: "catch (Exception)", Keys: []string{"catch", "exception"}, Why: "Catch only the exception types you can handle. Do not catch Exception without a when filter.",
				Like: "Like a fishing net that catches everything, including what you must throw back.", Example: "// instead:\ncatch (IOException ex)\n{ _logger.LogError(ex, \"Save failed\"); }"},
			{Use: "throw ex;", Keys: []string{"throw"}, Why: "Inside a catch, write throw; on its own. throw; keeps the original stack trace, which shows where the error started.",
				Like: "Like forwarding a letter in its original envelope, with the first postmark.", Example: "// instead:\ncatch (DbException ex)\n{ _logger.LogError(ex, \"Save failed\"); throw; }"},
			{Use: "x == null", Why: "Write x is null. A type can overload ==; is null never calls it.",
				Like: "Like asking a stranger if the room is empty, instead of looking yourself.", Example: "// instead:\nif (user is null) return NotFound();"},
			{Use: "using inside namespace", Why: "Put using directives above the namespace. Inside it, a name can change meaning when a package adds a matching namespace.",
				Like: "Like a nickname that suddenly means someone else when a new neighbour moves in.", Example: "// instead:\nusing System.Text.Json;\nnamespace App.Services;"},
		}},
	},
}

var learnPHP = learnTopic{
	Name:   "PHP",
	Match:  []string{"php", ".php"},
	Source: "PHP Manual (php.net): type declarations, strings, arrays, classes, properties, property hooks, visibility, enums, match, functions, arrow functions, first class callables, operators, PDO, password FAQ, migration 7.4, 8.2 and 8.5 · PSR-1 · PSR-4 · PSR-12 · PER Coding Style 3.1 · Composer schema · PHPStan, PHP CS Fixer and PHPUnit home pages",
	Sections: []learnSection{
		{Title: "File start", Keys: []string{"<?", "?>"}, Items: []learnItem{
			{Use: "<?php", Why: "Every PHP file starts with <?php on its own line. Use only <?php and <?= tags (PSR-1). In a file with only PHP, leave out the closing ?> (PER).",
				Like: "Like the first page of a form that says what kind of form it is. A form with nothing else after it needs no end page.", Example: "<?php\n\nnamespace App;"},
			{Use: "declare(strict_types=1);", Keys: []string{"strict_types", "declare"}, Why: "Strict typing for calls made from this file. A value of the wrong scalar type then throws a TypeError instead of being converted. One exception: an int is accepted for a float.",
				Like: "Like a vending machine that takes only the exact coin, and hands back any other.", Example: "<?php\n\ndeclare(strict_types=1);"},
			{Use: "namespace App\\Models;", Keys: []string{"namespace"}, Why: "The file's namespace. It comes after <?php, the file comment and declare (PSR-12 order). One blank line between these blocks.",
				Like: "Like a postal address: country, town, street, then the house.", Example: "declare(strict_types=1);\n\nnamespace App\\Models;"},
			{Use: "use App\\Models\\User;", Keys: []string{"use"}, Why: "Imports a class name, so the code can write User. Write the full name with no leading backslash (PSR-12). Imports come after the namespace line.",
				Like: "Like saving a phone number under a short name.", Example: "namespace App\\Http;\n\nuse App\\Models\\User;"},
			{Use: "\"psr-4\": {\"App\\\\\": \"src/\"}", Keys: []string{"psr-4", "autoload", "composer.json"}, Why: "In composer.json under autoload: the class App\\Models\\User is loaded from src/Models/User.php. The prefix must end with a backslash (written \\\\ in JSON).",
				Like: "Like a library catalogue: the shelf follows from the label on the book.", Example: "\"autoload\": {\n  \"psr-4\": {\"App\\\\\": \"src/\"}\n}"},
			{Use: "declare or do, not both", Why: "A file should either declare classes and functions, or do things such as output, include or ini_set. Not both (PSR-1).",
				Like: "Like keeping the recipe book and the cooking apart: one holds recipes, the other uses them.", Example: "<?php\nrequire __DIR__ . '/../vendor/autoload.php';\n(new App\\Kernel())->run();"},
		}},
		{Title: "Types", Keys: []string{"int", "string", "bool", "float", "array"}, Items: []learnItem{
			{Use: "function f(int $n): string", Keys: []string{"function"}, Why: "Type declarations for parameters and the return value. With strict_types, a wrong type throws a TypeError. Property types need PHP 7.4+.",
				Like: "Like sockets shaped for one plug: only the right one fits.", Example: "function isAdult(int $age): bool {\n  return $age >= 18;\n}"},
			{Use: "?string", Why: "Nullable: a string or null (PHP 7.1+). ?string and string|null are the same.",
				Like: "Like a parking space that may hold one car, or stay empty.", Example: "public ?string $nickname = null;"},
			{Use: "int|string", Keys: []string{"|"}, Why: "A union type (PHP 8.0+): any of the listed types is accepted.",
				Like: "Like a ticket that is valid on the bus or the tram.", Example: "function format(int|float $n): string {\n  return number_format($n, 2);\n}"},
			{Use: "void · never · mixed", Keys: []string{"void", "never", "mixed"}, Why: "void returns nothing (7.1+). never means the function never returns: it throws or exits (8.1+). mixed accepts any value (8.0+).",
				Like: "Like three signs: 'no exit', 'one way out, never back' and 'anything goes'.", Example: "function fail(string $message): never {\n  throw new RuntimeException($message);\n}"},
			{Use: "public readonly int $id;", Keys: []string{"readonly"}, Why: "A readonly property (PHP 8.1+) is set once, then never changes. It must have a type.",
				Like: "Like the ink on a passport page: written once, then fixed.", Example: "public function __construct(\n  public readonly int $id,\n) {}"},
			{Use: "const int MAX = 10;", Keys: []string{"const"}, Why: "Class constants can have a type (PHP 8.3+). Name them in capitals with underscores (PSR-1).",
				Like: "Like the boiling point of water printed in a book: it never changes.", Example: "class Config {\n  public const int MAX_RETRIES = 3;\n}"},
		}},
		{Title: "Strings and arrays", Keys: []string{"\"", "'"}, Items: []learnItem{
			{Use: "\"Hi {$name}\"", Keys: []string{"{$"}, Why: "Double quotes fill in variables. The braces show exactly where the variable ends. Single quotes keep the text as written.",
				Like: "Like a form letter: the name is written into the blank.", Example: "echo \"Hi {$user->name}, you have {$count} messages\";"},
			{Use: ".", Keys: []string{".="}, Why: "Joins strings: 'a' . 'b'. .= adds to the end of a string.",
				Like: "Like coupling two train carriages together.", Example: "$fullName = $first . ' ' . $last;\n$html .= '<li>' . $item . '</li>';"},
			{Use: "['id' => 1, 'name' => 'Ana']", Keys: []string{"=>", "array"}, Why: "Short array syntax. A PHP array is an ordered map: each value has a key. Without keys, the keys are 0, 1, 2 …",
				Like: "Like a filled-in form: each answer sits next to its label, in order.", Example: "$user = ['id' => 1, 'name' => 'Ana'];\n$tags = ['php', 'web'];\necho $user['name'];"},
			{Use: "str_contains($text, 'x')", Keys: []string{"str_contains"}, Why: "True when the text holds the other text (PHP 8.0+). It is case-sensitive.",
				Like: "Like looking for a word on a page.", Example: "if (!str_contains($email, '@')) {\n  throw new InvalidArgumentException('Bad email');\n}"},
			{Use: "<<<TXT", Keys: []string{"<<<"}, Why: "A heredoc: text over several lines, with variables filled in. <<<'TXT' (a nowdoc) keeps the text exactly as written.",
				Like: "Like a sealed envelope that holds a whole page as written.", Example: "$html = <<<HTML\n  <h1>{$title}</h1>\n  HTML;"},
			{Use: "...$items", Keys: []string{"..."}, Why: "In a parameter list, ...$items collects any number of arguments into an array. In a call, it unpacks an array into arguments.",
				Like: "Like a bag that takes as many items as you hand it.", Example: "function sum(int ...$numbers): int {\n  return array_sum($numbers);\n}"},
		}},
		{Title: "Comparison and null", Keys: []string{"if", "null", "isset"}, Items: []learnItem{
			{Use: "===", Keys: []string{"!=="}, Why: "Identical: the same value and the same type. Use it for checks.",
				Like: "Like checking both the name and the photo on an ID card.", Example: "if ($count === 0) {\n  return [];\n}"},
			{Use: "??", Why: "a ?? b gives b when a is null or does not exist. Like isset(), it gives no warning for a missing array key.",
				Like: "Like 'use the spare key if the main key is missing'.", Example: "$page = $_GET['page'] ?? 1;\n$name = $user->nickname ?? $user->name;"},
			{Use: "??=", Why: "Sets a value only when it is null or missing (PHP 7.4+): $opts['size'] ??= 10;",
				Like: "Like filling a glass only when it is empty.", Example: "$options['timeout'] ??= 30;\n$this->cache[$key] ??= $this->load($key);"},
			{Use: "?->", Why: "Nullsafe (PHP 8.0+). When the object is null, the result is null and the rest of the chain is skipped. Use it where null is expected; throw an exception for errors.",
				Like: "Like knocking before you go in: if nobody is home, you walk on.", Example: "$country = $user?->getAddress()?->country;"},
			{Use: "match ($x) { … }", Keys: []string{"match", "default"}, Why: "Returns a value by comparing with === (PHP 8.0+). Several values can share an arm: 1, 2 => …. A value with no arm throws an UnhandledMatchError.",
				Like: "Like a ticket gate that opens only for an exact ticket, and calls staff for anything else.", Example: "$label = match ($code) {\n  200, 201 => 'OK', 404 => 'Not found', default => 'Error',\n};"},
			{Use: "<=>", Why: "Gives an int below, equal to or above zero when the left side is less than, equal to or greater than the right side.",
				Like: "Like a balance scale: it tips left, stays level or tips right.", Example: "usort($users, fn($a, $b) => $a->age <=> $b->age);"},
		}},
		{Title: "Classes and enums", Keys: []string{"class", "new", "$this", "interface", "->"}, Items: []learnItem{
			{Use: "__construct(private int $id)", Keys: []string{"__construct"}, Why: "Constructor promotion (PHP 8.0+). A parameter with a visibility or readonly is also a property, and is set for you.",
				Like: "Like a coat hook with your name on it: hang the coat and it is already in its place.", Example: "public function __construct(\n  private UserRepository $users,\n) {}"},
			{Use: "readonly class Point", Why: "Every property becomes readonly (PHP 8.2+). Dynamic properties are not allowed. A child class must also be readonly.",
				Like: "Like a sealed museum case: you can look, not touch.", Example: "final readonly class Money {\n  public function __construct(public int $cents) {}\n}"},
			{Use: "enum Suit: string", Keys: []string{"enum", "tryfrom", "from"}, Why: "An enum (PHP 8.1+) is a fixed set of cases. A backed enum gives each case an int or string value. Suit::from('H') throws on an unknown value; tryFrom gives null.",
				Like: "Like the four suits in a deck of cards: no fifth suit can sneak in.", Example: "enum Status: string {\n  case Paid = 'paid';\n}"},
			{Use: "public private(set) string $x", Keys: []string{"private(set)", "protected(set)"}, Why: "Asymmetric visibility (PHP 8.4+). Anyone can read the property; only the class can write it.",
				Like: "Like a notice board behind glass: everyone can read it, only the office changes it.", Example: "class User {\n  public private(set) string $name = '';\n}"},
			{Use: "property hooks: get · set", Keys: []string{"get", "set"}, Why: "Property hooks (PHP 8.4+) run code when a property is read (get) or written (set). They replace most getter and setter methods. Not with readonly.",
				Like: "Like a doorman: you use the same door, but he can check you on the way in or out.", Example: "public string $email {\n  set => strtolower($value);\n}"},
			{Use: "#[\\Override]", Keys: []string{"override"}, Why: "Marks a method that must replace a parent method (PHP 8.3+). If no parent method has that name, PHP stops with an error.",
				Like: "Like a new key labelled 'replaces the old one': if there is no old lock, you notice at once.", Example: "#[\\Override]\nprotected function setUp(): void { parent::setUp(); }"},
		}},
		{Title: "Functions", Keys: []string{"return", "callable"}, Items: []learnItem{
			{Use: "fn($x) => $x * 2", Keys: []string{"fn"}, Why: "An arrow function (PHP 7.4+). Its one expression is returned. Variables from outside are captured by value, with no use ( ).",
				Like: "Like a sticky note with one instruction: short, and it copies what it needs from the desk.", Example: "$names = array_map(fn($u) => $u->name, $users);\n$adults = array_filter($users, fn($u) => $u->age >= 18);"},
			{Use: "f(limit: 10)", Why: "Named arguments (PHP 8.0+). Pass values by parameter name, in any order, and skip defaults. Named ones come after positional ones.",
				Like: "Like labelled jars: the order on the shelf does not matter.", Example: "$safe = htmlspecialchars($text, double_encode: false);\n$first = array_slice($items, 0, 5, preserve_keys: true);"},
			{Use: "strlen(...)", Why: "First class callable syntax (PHP 8.1+). It makes a Closure from a function or method. The ... is part of the syntax. It replaces callables written as strings or arrays.",
				Like: "Like handing someone the tool itself, not a note with its name.", Example: "$lengths = array_map(strlen(...), $words);\n$handler = $this->handle(...);"},
			{Use: "$x |> f(...)", Keys: []string{"|>"}, Why: "The pipe operator (PHP 8.5+). It passes the value on the left to the callable on the right: \"Hi\" |> strlen(...) gives 2.",
				Like: "Like a conveyor belt that carries a part from one machine to the next.", Example: "$slug = $title\n  |> trim(...)\n  |> strtolower(...);"},
		}},
		{Title: "Style and tools", Keys: []string{"//", "/**"}, Items: []learnItem{
			{Use: "StudlyCaps · camelCase", Why: "Class names in StudlyCaps: UserRepository. Method names in camelCase: findById (PSR-1).",
				Like: "Like capital letters on town names, and small ones for the streets inside.", Example: "$repo = new UserRepository();\n$user = $repo->findById(42);"},
			{Use: "UPPER_CASE", Why: "Class constants: all capitals, with underscores between words (PSR-1).",
				Like: "Like a road sign: big letters, read at a glance, never changed.", Example: "class Cart {\n  public const MAX_ITEMS = 50;\n}"},
			{Use: "4 spaces", Why: "Indent with 4 spaces, never tabs (PER). Keywords and types in lower case. Short type names: bool and int, not boolean and integer.",
				Like: "Like ruled paper: every line starts at the same margin.", Example: "if ($user->isAdmin()) {\n    $this->grantAccess($user);\n}"},
			{Use: "{ on its own line", Why: "Braces of classes, methods and functions go on their own line. For if, for, while and the like, the brace stays on the same line (PSR-12, PER).",
				Like: "Like a chapter title on its own line, while sentences flow on.", Example: "class OrderService\n{\n}"},
			{Use: "public function", Keys: []string{"public", "private", "protected"}, Why: "Always write the visibility of properties, methods and constants (PER). Never use var for a property. A leading _ has no meaning.",
				Like: "Like a door sign that says 'public' or 'staff only', so nobody has to guess.", Example: "private int $count = 0;\nprotected const LIMIT = 10;\npublic function count(): int { return $this->count; }"},
			{Use: "PHPStan · PHP CS Fixer", Keys: []string{"phpstan", "php-cs-fixer"}, Why: "PHPStan finds bugs without writing tests; start at a low rule level. PHP CS Fixer rewrites code to a style, such as its @PER-CS rule set.",
				Like: "Like a proofreader and a typesetter: one finds mistakes, one makes the pages match.", Example: "vendor/bin/phpstan analyse src --level 5\nvendor/bin/php-cs-fixer fix src"},
			{Use: "PHPUnit", Keys: []string{"phpunit", "testcase"}, Why: "The testing framework for PHP: write tests for your code and run them.",
				Like: "Like a checklist you run before every trip, the same each time.", Example: "composer require --dev phpunit/phpunit\nvendor/bin/phpunit tests"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "==", Keys: []string{"!=", "<>"}, Why: "== compares after type juggling: it converts types first, so values of different types can count as equal. Use ===.",
				Like: "Like a cashier who accepts a drawing of a coin because it looks like one.", Example: "// instead:\n$isAdmin = $role === 'admin';"},
			{Use: "\"${var}\"", Keys: []string{"${"}, Why: "Deprecated since PHP 8.2. Write \"$var\" or \"{$var}\".",
				Like: "Like an old plug that no longer fits the wall socket.", Example: "// instead:\necho \"Hello {$name}\";"},
			{Use: "SQL built with .", Keys: []string{"query", "prepare", "pdo"}, Why: "Use PDO prepared statements: prepare('… WHERE id = ?'), then execute([$id]). The driver quotes the values, which stops SQL injection.",
				Like: "Like a form with fixed boxes: whatever someone writes stays inside its box.", Example: "// instead:\n$stmt = $pdo->prepare('SELECT * FROM users WHERE id = ?');\n$stmt->execute([$id]);"},
			{Use: "md5($password)", Keys: []string{"md5", "sha1", "password_hash", "password_verify"}, Why: "MD5, SHA1 and SHA256 are too fast to protect passwords. Use password_hash($p, PASSWORD_DEFAULT) and password_verify().",
				Like: "Like a lock that a thief can try a billion keys on every second.", Example: "// instead:\n$hash = password_hash($password, PASSWORD_DEFAULT);\n$ok = password_verify($password, $hash);"},
			{Use: "@", Why: "The @ operator hides error messages from an expression. The error still happened. Check the result instead.",
				Like: "Like taping over a warning light on the dashboard.", Example: "// instead:\n$text = file_get_contents($path);\nif ($text === false) throw new RuntimeException('No file');"},
			{Use: "extract($_GET)", Keys: []string{"extract"}, Why: "Never use extract() on user input such as $_GET or $_FILES. It turns array keys into variables and can overwrite yours.",
				Like: "Like letting strangers write labels on your kitchen jars.", Example: "// instead:\n$page = (int) ($_GET['page'] ?? 1);\n$query = $_GET['q'] ?? '';"},
		}},
	},
}
